import pytest
from units_core import Q, DimensionError

def test_add_like():
    assert (Q(2, 'm') + Q(3, 'm')).value == 5

def test_add_unlike_raises():
    with pytest.raises(DimensionError):
        Q(2, 'm') + Q(1, 's')

