    assert f.dim == {'kg': 1, 'm': 1, 's': -2}

def test_pow():
    a = Q(3, 'm') ** 2
    assert a.value == 9 and a.dim == {'m': 2}

def test_dimensionless_cancel():
    r = Q(6, 'm') / Q(2, 'm')
