"""Minimal quantity library with dimensional analysis (TDD implementation)."""

import re


class DimensionError(Exception):
    """Raised when quantities with incompatible dimensions are combined."""


def _parse_unit(spec):
    """Parse a unit string like 'm', 'kg', 'm/s', 'm s^-1' into a dim dict."""
    if not spec:
        return {}
    dim = {}
    tokens = re.findall(r"[*/]|[^*/\s]+", spec)
    multiply = True
    for tok in tokens:
        if tok == "*":
            multiply = True
            continue
        if tok == "/":
            multiply = False
            continue
        base, sep, exp = tok.partition("^")
        exp = int(exp) if sep else 1
        if not multiply:
            exp = -exp
        dim[base] = dim.get(base, 0) + exp
    return {k: v for k, v in dim.items() if v != 0}


class Q:
    """A physical quantity: a numeric value plus a dimension dict."""

    def __init__(self, value, unit=""):
        self.value = float(value)
        self.dim = _parse_unit(unit)

    def _combine(self, other, sign):
        if self.dim != other.dim:
            raise DimensionError(
                f"incompatible dimensions: {self.dim} vs {other.dim}"
            )
        return Q(self.value + sign * other.value, "")

    def __add__(self, other):
        return self._combine(other, 1)

    def __sub__(self, other):
        return self._combine(other, -1)

    def _merge(self, other, sign):
        dim = dict(self.dim)
        for base, exp in other.dim.items():
            new = dim.get(base, 0) + sign * exp
            if new == 0:
                dim.pop(base, None)
            else:
                dim[base] = new
        return Q(self.value * other.value, "")

    def __mul__(self, other):
        return self._merge(other, 1)

    def __truediv__(self, other):
        return self._merge(other, -1)

    def __pow__(self, exponent):
        dim = {}
        for base, exp in self.dim.items():
            new = exp * exponent
            if new != 0:
                dim[base] = new
        return Q(self.value ** exponent, "")

    @property
    def unit_str(self):
        parts = []
        for base in sorted(self.dim):
            exp = self.dim[base]
            parts.append(base if exp == 1 else f"{base}^{exp}")
        return " ".join(parts)

    def __str__(self):
        if self.dim:
            return f"{self.value} {self.unit_str}"
        return f"{self.value}"

    def __repr__(self):
        return f"Q({self.value}, '{self.unit_str}')"

